package com.tiendatech.ordenesproveedores.infrastructure.observability;
import io.micrometer.core.instrument.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.concurrent.TimeUnit;import java.util.concurrent.atomic.AtomicInteger;
@Component public class HttpObservabilityFilter extends OncePerRequestFilter{
    private static final Logger LOG=LoggerFactory.getLogger(HttpObservabilityFilter.class);private final MeterRegistry registry;private final AtomicInteger active=new AtomicInteger();private final String service;public HttpObservabilityFilter(MeterRegistry registry,@Value("${spring.application.name}")String service)
    {this.registry=registry;this.service=service;Gauge.builder("active_connections",active,AtomicInteger::get).tag("service",service).register(registry);}
    @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{long start=System.nanoTime();active.incrementAndGet();try{chain.doFilter(req,res);}finally{long elapsed=System.nanoTime()-start;active.decrementAndGet();String route=req.getRequestURI(),status=Integer.toString(res.getStatus());Counter.builder("request_count").tags("service",service,"method",req.getMethod(),"route",route,"status",status).register(registry).increment();Timer.builder("request_duration").publishPercentileHistogram().tags("service",service,"method",req.getMethod(),"route",route,"status",status).register(registry).record(elapsed,TimeUnit.NANOSECONDS);MDC.put("service",service);MDC.put("method",req.getMethod());MDC.put("route",route);MDC.put("status",status);MDC.put("response_time_ms",Long.toString(TimeUnit.NANOSECONDS.toMillis(elapsed)));LOG.info("http_request_completed");MDC.clear();}}}


